.glow {
  position: absolute;
  width: 480px;
  height: 480px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(99, 102, 241, 0.35), transparent 70%);
  filter: blur(60px);
  pointer-events: none;
}

type MyPartial<T> = {
  [K in keyof T]?: T[K]
}

type User = { name: string; age: number }
type PartialUser = MyPartial<User>
// { name?: string; age?: number }

:root {
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 16px;
  --radius-sm: 8px;
  --radius-md: 14px;
  --radius-lg: 22px;
  --ease-out: cubic-bezier(0.22, 1, 0.36, 1);
}
